        return RappSessionBridge(UniffiWithHandle, value)
    }

    override fun read(buf: ByteBuffer): RappSessionBridge {
        return lift(buf.getLong())
    }

    override fun allocationSize(value: RappSessionBridge) = 8UL

    override fun write(value: RappSessionBridge, buf: ByteBuffer) {
        buf.putLong(lower(value))
    }
}



