/**
 * Deliberately coarse binding failure. Protocol internals and secrets never
 * become UI strings or foreign-language log material.
 */
sealed class RappBindingException: kotlin.Exception() {
    
    /**
     * Caller-provided bytes or registry values were invalid.
     */
    class InvalidInput(
        ) : RappBindingException() {
        override val message
            get() = ""
    }
    
    /**
     * Method was not legal in the current protocol phase.
     */
    class WrongPhase(
        ) : RappBindingException() {
        override val message
            get() = ""
    }
    
    /**
     * The one-use pairing offer reached its monotonic deadline.
     */
    class OfferExpired(
        ) : RappBindingException() {
        override val message
            get() = ""
    }
    
    /**
     * Authenticated protocol or cryptographic processing failed.
     */
    class ProtocolFailure(
        ) : RappBindingException() {
        override val message
            get() = ""
    }
    
    /**
     * Local synchronization state was poisoned and cannot be reused.
     */
    class LocalStateFailure(
        ) : RappBindingException() {
        override val message
            get() = ""
    }
    
    /**
     * Requested active pair record was not present in device-only storage.
     */
    class PairNotFound(
        ) : RappBindingException() {
        override val message
            get() = ""
    }
    
    /**
     * Referenced operation was not found in the active session.
     */
    class UnknownOperation(
        ) : RappBindingException() {
        override val message
            get() = ""
    }
    

    


    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<RappBindingException> {
        override fun lift(error_buf: RustBuffer.ByValue): RappBindingException = FfiConverterTypeRappBindingError.lift(error_buf)
    }

    
}

/**
 * @suppress
 */
public object FfiConverterTypeRappBindingError : FfiConverterRustBuffer<RappBindingException> {
    override fun read(buf: ByteBuffer): RappBindingException {
        

        return when(buf.getInt()) {
            1 -> RappBindingException.InvalidInput()
            2 -> RappBindingException.WrongPhase()
            3 -> RappBindingException.OfferExpired()
            4 -> RappBindingException.ProtocolFailure()
            5 -> RappBindingException.LocalStateFailure()
            6 -> RappBindingException.PairNotFound()
            7 -> RappBindingException.UnknownOperation()
            else -> throw RuntimeException("invalid error enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: RappBindingException): ULong {
        return when(value) {
            is RappBindingException.InvalidInput -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is RappBindingException.WrongPhase -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is RappBindingException.OfferExpired -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is RappBindingException.ProtocolFailure -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is RappBindingException.LocalStateFailure -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is RappBindingException.PairNotFound -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is RappBindingException.UnknownOperation -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
        }
    }

    override fun write(value: RappBindingException, buf: ByteBuffer) {
        when(value) {
            is RappBindingException.InvalidInput -> {
                buf.putInt(1)
                Unit
            }
            is RappBindingException.WrongPhase -> {
                buf.putInt(2)
                Unit
            }
            is RappBindingException.OfferExpired -> {
                buf.putInt(3)
                Unit
            }
            is RappBindingException.ProtocolFailure -> {
                buf.putInt(4)
                Unit
            }
            is RappBindingException.LocalStateFailure -> {
                buf.putInt(5)
                Unit
            }
            is RappBindingException.PairNotFound -> {
                buf.putInt(6)
                Unit
            }
            is RappBindingException.UnknownOperation -> {
                buf.putInt(7)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }

}



/**
 * Bounded action produced by the authoritative Rust state machine.
 */

enum class RappBridgeActionKind {
    
    /**
     * Deliver one opaque encrypted frame to the transport.
     */
    SEND_FRAME,
    /**
     * Perform the profile's safe prerequisite inspection.
     */
    INSPECT_PREREQUISITES,
    /**
