/**
 * Platform vault failure, intentionally free of backend strings or secrets.
 */
sealed class RappVaultException: kotlin.Exception() {
    
    /**
     * Secret storage was unavailable or rejected the atomic operation.
     */
    class Unavailable(
        ) : RappVaultException() {
        override val message
            get() = ""
    }
    
    /**
     * Identifier already has an active record or permanent tombstone.
     */
    class IdentifierAlreadyUsed(
        ) : RappVaultException() {
        override val message
            get() = ""
    }
    
    /**
     * Requested active pair did not exist.
     */
    class PairNotFound(
        ) : RappVaultException() {
        override val message
            get() = ""
    }
    

    


    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<RappVaultException> {
        override fun lift(error_buf: RustBuffer.ByValue): RappVaultException = FfiConverterTypeRappVaultError.lift(error_buf)
    }

    
}

/**
 * @suppress
 */
public object FfiConverterTypeRappVaultError : FfiConverterRustBuffer<RappVaultException> {
    override fun read(buf: ByteBuffer): RappVaultException {
        

        return when(buf.getInt()) {
            1 -> RappVaultException.Unavailable()
            2 -> RappVaultException.IdentifierAlreadyUsed()
            3 -> RappVaultException.PairNotFound()
            else -> throw RuntimeException("invalid error enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: RappVaultException): ULong {
        return when(value) {
            is RappVaultException.Unavailable -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is RappVaultException.IdentifierAlreadyUsed -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is RappVaultException.PairNotFound -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
        }
    }

    override fun write(value: RappVaultException, buf: ByteBuffer) {
        when(value) {
            is RappVaultException.Unavailable -> {
                buf.putInt(1)
                Unit
            }
            is RappVaultException.IdentifierAlreadyUsed -> {
                buf.putInt(2)
                Unit
            }
            is RappVaultException.PairNotFound -> {
                buf.putInt(3)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }

}




